use privai_chain::canonical::canonical_bytes;
use privai_chain::hash::*;
use privai_chain::note::*;
use privai_chain::primitives::*;
use privai_chain::tx::*;

fn to_hex(data: &[u8]) -> String {
    data.iter()
        .map(|b| format!("{:02x}", b))
        .collect::<String>()
}

#[test]
fn test_reference_vectors_fullprivacy() {
    // --- RECEIVE BUNDLE ---
    let bundle = ReceiveBundle {
        version: 0,
        bundle_id: [0xaa; 16],
        expires_at: 4048807168,
        flags: 0,
        one_time_falcon_pk: [0x10; 897].to_vec(),
        one_time_frodo_pk: [0x20; 9616].to_vec(),
        route_hint: Some([0x01; 64].to_vec()),
        nullifier_key: [0xbb; 32],
    };
    assert_eq!(to_hex(&canonical_bytes(&bundle)), "");
    assert_eq!(
        to_hex(&bundle.commitment()),
        "d2a2ac6720cf5d9e50bd6bc0deb9813403261af8ba493295ac78637ddc5b6373"
    );

    // --- SPEND POLICY SINGLE ---
    let sp_single = SpendPolicy::Single {
        falcon_pk_hash: [0x03; 32],
    };
    assert_eq!(
        to_hex(&canonical_bytes(&sp_single)),
        "010303030303030303030303030303030303030303030303030303030303030303"
    );
    assert_eq!(
        to_hex(&sp_single.commitment()),
        "58db5dbb1fff82ab96cd3765407719c5ef303dd8525c4354ffebcd40924329e6"
    );

    // --- SPEND POLICY MARKETPLACE ---
    let sp_market = SpendPolicy::MarketplaceSettlement {
        buyer_pk_hash: [0x04; 32],
        seller_pk_hash: [0x05; 32],
        moderator_pk_hash: [0x06; 32],
        timeout_block: 1_000_000,
    };
    assert_eq!(to_hex(&canonical_bytes(&sp_market)), "0204040404040404040404040404040404040404040404040404040404040404040505050505050505050505050505050505050505050505050505050505050505060606060606060606060606060606060606060606060606060606060606060640420f0000000000");
    assert_eq!(
        to_hex(&sp_market.commitment()),
        "537b90514d92473792dbf6265cd13761893553276f2b045c117f9068b14d37c1"
    );

    // --- RECIPIENT BOX ---
    let recipient_box = RecipientBox {
        version: 0,
        kem_alg: 1,
        aead_alg: 1,
        kem_ct: [0x30, 0x31, 0x32].to_vec(),
        nonce: [0x40; 24],
        ciphertext: [0x50, 0x51].to_vec(),
        tag: [0x60; 16],
        hint: [0x70; 16],
    };
    assert_eq!(to_hex(&canonical_bytes(&recipient_box)), "000101030000003031324040404040404040404040404040404040404040404040400200000050516060606060606060606060606060606070707070707070707070707070707070");

    // --- RECIPIENT BOX PLAINTEXT ---
    let rbp = RecipientBoxPlaintext {
        version: 0,
        bundle_id: [0xaa; 16],
        note_payload_commit: [0xdd; 32],
        amount: Amount14::new(100).unwrap(),
        witness_seed: [0xee; 32],
        nullifier_key: [0xff; 32],
        spend_policy_opening: [0x11, 0x22].to_vec(),
        aux_opening: [0x33, 0x44].to_vec(),
        sender_memo: Some([0x55, 0x66].to_vec()),
    };
    assert_eq!(to_hex(&canonical_bytes(&rbp)), "00aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaadddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd6400eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff02000000112202000000334401020000005566");

    // --- AUX WITNESS ---
    let aux = AuxWitness {
        version: 0,
        amount: Amount14::new(42).unwrap(),
        witness_seed: [0x02; 32],
        noise_class: 0,
        bundle_id: [0xaa; 16],
    };
    assert_eq!(to_hex(&canonical_bytes(&aux)), "002a00020202020202020202020202020202020202020202020202020202020202020200aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
    assert_eq!(
        to_hex(&derive_aux_commit(&aux)),
        "452113efbf91ea02706f6a1b5d7a68d13896e2fea1b13530eb90d8b6b150af77"
    );

    // --- OUTPUT NOTE ---
    let note = OutputNote::new(
        sp_single.commitment(),
        LweCiphertext::new([0; 1024].to_vec(), 0).unwrap(),
        derive_aux_commit(&aux),
        recipient_box.clone(),
    );
    assert_eq!(to_hex(&note.payload_bytes()), "");
    assert_eq!(
        to_hex(&note.payload_commit()),
        "5d55db87f16c4781c83c02e2d6a11c5627157e40216e096bc79f3cbe6853afc3"
    );
    assert_eq!(to_hex(&canonical_bytes(&note)), "");
    assert_eq!(
        to_hex(&note.note_commit),
        "2854243f983fec698e8cfaf72241ba6a783d3e4ca16ec602feb94019fc876397"
    );

    // --- NULLIFIER DERIVATION ---
    let nullifier_key = [0xdd; 32];
    let nullifier = derive_nullifier(&note.note_commit, &nullifier_key);
    assert_eq!(
        to_hex(&nullifier.0),
        "7180bbad0931f8f1881c37a4ad994f62b214616d37fff6b3d6a361715c9da4e1"
    );

    // --- TRANSFER NOTE TX ---
    let tx = TransferNoteTx {
        core: TxCore {
            version: 0,
            tx_type: TX_TYPE_TRANSFER_NOTE,
            inputs: vec![InputRef {
                note_commit: note.note_commit,
            }],
            input_nullifiers: vec![nullifier.clone()],
            outputs: vec![note.clone()],
            fee: 10,
            statement_commit: [0x88; 32],
            auth: vec![InputAuth {
                policy_tag: 0,
                signer_pks: vec![[0x99; 897].to_vec()],
                signatures: vec![[0x77; 666].to_vec()],
            }],
        },
    };
    assert_eq!(to_hex(&canonical_bytes(&tx)), "");

    // --- TX ROOT EXAMPLE ---
    let tx_id1: Hash32 = [0x11; 32];
    let tx_id2: Hash32 = [0x22; 32];
    let tx_id3: Hash32 = [0x33; 32];
    let leaves = vec![tx_id1, tx_id2, tx_id3];
    let tx_root = merkle_root(leaves.into_iter());
    assert_eq!(
        to_hex(&tx_root),
        "d5e5a203522e9f7f0b25910223babcd45aac63a403bceb19a6cd4a698a615606"
    );

    // --- NONE VS SOME BOUNDARY ---
    let mut b_none = bundle.clone();
    b_none.route_hint = None;
    let mut b_some = bundle.clone();
    b_some.route_hint = Some([0x01, 0x02, 0x03].to_vec());
    assert_eq!(to_hex(&canonical_bytes(&b_none)), "");
    assert_eq!(to_hex(&canonical_bytes(&b_some)), "");

    // --- MUTATION TEST ---
    let mut b_mut = b_none.clone();
    b_mut.flags = 1;
    assert_eq!(
        to_hex(&b_none.commitment()),
        "9a327161d94b2478d0abcc30ed54e7c96f45908168634bcadd2080bf7c8c03fe"
    );
    assert_eq!(
        to_hex(&b_mut.commitment()),
        "4f37aaf0d8b88be379e5c0838fcc0e564581a98fd53fa76c85e6516c275ead9e"
    );
    assert!(to_hex(&b_none.commitment()) != to_hex(&b_mut.commitment()));

    // --- TX ID ---
    let transaction = Transaction::TransferNote(tx);
    let tx_id = transaction.tx_id();
    assert_eq!(
        to_hex(&tx_id),
        "b2ad58b358d9a409e810d10b35767ee7a3a5ba6b20d27a58c099dd559b9714a3"
    );

    // --- NONE VS SOME COMMIT DIFFERS ---
    assert_eq!(
        to_hex(&b_none.commitment()),
        "9a327161d94b2478d0abcc30ed54e7c96f45908168634bcadd2080bf7c8c03fe"
    );
    assert_eq!(
        to_hex(&b_some.commitment()),
        "5c0d82bf64ff59fd2be3bed67d470ed503140c950d50b58dd62be65aff545865"
    );
    assert_ne!(b_none.commitment(), b_some.commitment());
}
